module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    // Define the output signal 'diff' for the difference between 'a' and 'b'.
    // This signal will be all zeros if 'a' equals 'b'.
    wire [3:0] diff;

    assign diff = a ^ b;

    // The output 'equal' is the bitwise NOR of the 'diff' signal.
    // If all bits in 'diff' are 0, then 'diff' NOR 'diff' is 1.
    assign equal = ~((diff[0] | diff[1]) | (diff[2] | diff[3]));

    // Alternatively, you could use the system function to compare vectors directly:
    // assign equal = (a == b) ? 1'b1 : 1'b0;

endmodule

