module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

  // Define states (2 bits = 4 states)
  // S0: Idle
  // S1: Moving Up / Stopped at a floor going up
  // S2: Moving Down / Stopped at a floor going down
  // S3: Handling requests or error state (unused here, but reserved)

  reg [1:0] current_state, next_state;

  // State encoding
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  always @(posedge clk or posedge reset) begin
    if (reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Combinational logic to determine next state
  always @(*) begin
    next_state = current_state; // Default to current state
    case (current_state)
      S0: begin
        if (up_request)
          next_state = S1;
        else if (down_request)
          next_state = S2;
        else
          next_state = S0;
      end

      S1: begin 
        // Assume this state represents moving up or arriving at a target
        if (down_request) begin
          next_state = S2; // User says go down, switch direction
        end else begin
          next_state = S1; // Continue or stay in up state
        end
      end

      S2: begin 
        // Assume this state represents moving down or arriving at a target
        if (up_request) begin
          next_state = S1; // User says go up, switch direction
        end else begin
          next_state = S2; // Continue or stay in down state
        end
      end

      default: next_state = S0;
    endcase
  end

  // Assign the output state
  assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] state;
parameter IDLE = 2'b00;
parameter WAITING = 2'b01;
parameter DRIPPING = 2'b10;
parameter READY = 2'b11;

always @(posedge clk or posedge reset) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state(state, coin_inserted, item_selected);
end

function [1:0] next_state;
    input [1:0] current_state;
    input coin_inserted, item_selected;

    case (current_state)
        IDLE: begin
            if (coin_inserted)
                next_state <= WAITING;
            else
                next_state <= IDLE;
        end
        WAITING: begin
            if (item_selected)
                next_state <= DRIPPING;
            else if (coin_inserted)
                next_state <= WAITING;
            else
                next_state <= IDLE;
        end
        DRIPPING: begin
            if (item_selected)
                next_state <= READY;
            else
                next_state <= DRIPPING;
        end
        READY: begin
            if (item_selected)
                next_state <= IDLE;
            else
                next_state <= READY;
        end
        default: next_state <= IDLE; // For safety
    endcase
endfunction

endmodule

