module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    reg [7:0] temp;
    reg [3:0] b;

    always @(in or b or shift) begin
        temp = in;
        b = shift;
        if (b[2]) begin
            for (integer i = 0; i < 3; i = i + 1)
                temp = {(temp[6:0]), temp[7]};
        end
        else if (b[1]) begin
            for (integer i = 0; i < 2; i = i + 1)
                temp = {(temp[6:0]), temp[7]};
        end
        else if (b[0])
            temp = {(temp[6:0]), temp[7]};
        out = temp;
    end

endmodule

