module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire n_a0, n_a1, n_a2, n_a3;
    wire n_b0, n_b1, n_b2, n_b3;
    assign n_a0 = ~a[0];
    assign n_a1 = ~a[1];
    assign n_a2 = ~a[2];
    assign n_a3 = ~a[3];
    assign n_b0 = ~b[0];
    assign n_b1 = ~b[1];
    assign n_b2 = ~b[2];
    assign n_b3 = ~b[3];

    assign eq = (a[0] == n_b0) & (a[1] == n_b1) & (a[2] == n_b2) & (a[3] == n_b3);
    assign gt = (a[3] == n_b3) | ((a[3] > n_b3) & (a[2] == n_b2)) |
                 ((a[3] == n_b3) & (a[2] == n_b2) & (a[1] > n_b1)) |
                 ((a[3] == n_b3) & (a[2] == n_b2) & (a[1] == n_b1) & (a[0] > n_b0));
    assign lt = (a[3] == n_b3) | ((a[3] < n_b3) & (a[2] == n_b2)) |
                 ((a[3] == n_b3) & (a[2] == n_b2) & (a[1] < n_b1)) |
                 ((a[3] == n_b3) & (a[2] == n_b2) & (a[1] == n_b1) & (a[0] < n_b0));
endmodule

