module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
    // Internal binary counter
    reg [7:0] binary_count;

    // Logic to convert binary count to Gray code
    // The n-th bit of the Gray code is the exclusive OR of the n-th and (n+1)-th bits of the binary code
    assign count[7] = binary_count[7];
    assign count[6] = binary_count[7] ^ binary_count[6];
    assign count[5] = binary_count[6] ^ binary_count[5];
    assign count[4] = binary_count[5] ^ binary_count[4];
    assign count[3] = binary_count[4] ^ binary_count[3];
    assign count[2] = binary_count[3] ^ binary_count[2];
    assign count[1] = binary_count[2] ^ binary_count[1];
    assign count[0] = binary_count[1] ^ binary_count[0];

    // Synchronous reset
    always @(posedge clk) begin
        if (rst)
            binary_count <= 8'd0;
        else
            binary_count <= binary_count + 1'b1;
    end

endmodule

