module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] g_reg;
  wire      [2:0] g_next;

  // Example logic: Simple counter with reset
  // If resetn is high (active low reset), g will be 3'b000
  // Otherwise, g will increment based on 'r'
  always @(*) begin
    g_next = 3'b000;
    if (resetn) begin
      g_next = 3'b000;
    end else begin
      g_next = r + 3'b001;
      if (g_next > 3'b111) begin
        g_next = 3'b000;
      end
    end
  end

  // Synchronous register
  always @(posedge clk) begin
    if (resetn) begin
      g_reg <= 3'b000;
    end else begin
      g_reg <= g_next;
    end
  end

  assign g = g_reg;

endmodule

