module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input        Cin,
    output [3:0] Sum,
    output       Cout
);

    wire [3:0] sum_raw;
    wire       carry_raw;

    // First stage: 4-bit binary addition
    adder_4bit u1 (
        .a(A),
        .b(B),
        .cin(Cin),
        .s(sum_raw),
        .cout(carry_raw)
    );

    // BCD correction logic
    assign Cout = carry_raw || (sum_raw > 9);

    generate
        genvar i;
        begin : bcd_correct
            for (i = 0; i < 5; i = i + 1) do : body
                if (i == 5) begin
                    // Skip if no overflow
                    // This loop structure is for illustration; actual HDL may use other constructs
                end else begin
                    // Apply correction if sum exceeds 9
                    wire [3:0] temp_sum;
                    temporary temp_sum;
                    assign temp_sum = sum_raw;
                    end
                end
            end
        end
    endgenerate

    assign Sum = sum_raw + (Cout ? 4'b0101 : 4'b0000); // Simplified correction

    always @(*) begin
        if (Carry_raw || (Sum > 9)) begin
            Sum = Sum + 4'h3; // Corrective subtraction
            Carry_raw = 1;
        end
    end

    endmodule

