module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);
	reg next_rise;
	reg next_down;
	reg a_prev;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			a_prev <= 1'b0;
			next_rise <= 1'b0;
			next_down <= 1'b0;
		end
		else begin
			a_prev <= a;
			if (a && !a_prev) next_rise <= 1'b1;
			else next_rise <= 1'b0;

			if (!a && a_prev) next_down <= 1'b1;
			else next_down <= 1'b0;
		end
	end

	assign rise = next_rise;
	assign down = next_down;
endmodule

