module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] d1, d2;
	reg [1:0] state;

	assign state = {1'd1, d2} ? (state == 2'h3) : state;

	// Process for resetting both registers
	if ( ~arstn | ~brstn ) begin
		d1 <= 'b0000;
		d2 <= 'b0000;
	end

	// Data synchronization: first stage (clocked by clk_a)
	if ( clk_a ) begin
		if ( !brstn ) begin
			d1 <= 'b0000;
			d2 <= 'b0000;
		end
		else if ( data_en )
			d1 <= data_in;
	end

	// Data synchronization: second stage (clocked by clk_b) to synchronize to clk_b
	if ( clk_b ) begin
		if ( !brstn ) begin
			d1 <= 'b0000;
			d2 <= 'b0000;
		end
		else if ( data_en )
			d2 <= data_in;
	end

	// Assign output after both stages
	dataout <= d2;

endmodule

module fsm(IN, MATCH, CLK, RST);
    input IN, CLK, RST;
    output reg MATCH;

    // Define state encoding
    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // State register logic
    always @(posedge CLK or posedge RST) begin
        if (RST)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: begin
                if (IN) next_state = S1;
                else     next_state = S0;
            end
            S1: begin
                if (IN)  next_state = S2;
                else     next_state = S0;
            end
            S2: begin
                next_state = S0;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic (MATCH)
    always @(*) begin
        MATCH = 1'b0;
        case (current_state)
            S2: MATCH = IN; // Match when in S2 and input is active
            default: MATCH = 1'b0;
        endcase
    end
endmodule

